use vstd::prelude::*;

verus! {

fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        1 <= k,
        k < list.len(),
    ensures
        new_list.len() == list.len() - 1,
        // Elements before the removed position are unchanged
        forall|i: int|
            0 <= i && i < (k - 1) as int ==>
                new_list[i] == list[i],
        // Elements after the removed position shift left by 1
        forall|i: int|
            (k - 1) as int <= i && i < new_list.len() as int ==>
                new_list[i] == list[i + 1],
{
    let n = list.len();
    assert!(n > 0, "list must be non-empty");
    assert!(k >= 1 && k < n, "require 1 <= k < n (1-based indexing)");

    // Convert 1-based k to 0-based index.
    let remove_idx = k - 1;

    let mut new_list = Vec::with_capacity(n - 1);
    new_list.extend_from_slice(&list[..remove_idx]);
    new_list.extend_from_slice(&list[remove_idx + 1..]);
    new_list
}

} // verus!

